@Johnson：从linux4.15抽出部分代码。i2c地址有7bit和10bit，针对7bit地址，自然不能大于7f，检测代码如下。
of_i2c_register_device->i2c_check_addr_validity
int i2c_check_addr_validity(unsigned addr, unsigned short flags)
{
	if (flags & I2C_CLIENT_TEN) {
		/* 10-bit address, all values are valid */
		if (addr > 0x3ff)
			return -EINVAL;
	} else {
		/* 7-bit address, reject the general call address */
		if (addr == 0x00 || addr > 0x7f)
			return -EINVAL;
	}
	return 0;
}

@lcbj：取决你调用什么接口以及如何配置。例如下面的函数。
int gpiod_get_value(const struct gpio_desc *desc)
{
	int value;

	VALIDATE_DESC(desc);
	/* Should be using gpio_get_value_cansleep() */
	WARN_ON(desc->gdev->chip->can_sleep);

	value = gpiod_get_raw_value_commit(desc);
	if (value < 0)
		return value;

	if (test_bit(FLAG_ACTIVE_LOW, &desc->flags))
		value = !value;

	return value;
}
看看这个if (test_bit(FLAG_ACTIVE_LOW, &desc->flags))value = !value;你的疑问可以通过全局搜索FLAG_ACTIVE_LOW，或者你的driver调用的接口追踪函数是否用到该flag
